import re

_HEADER_RE = re.compile(r'^([a-z]+)(\(([^()]+)\))?(!)?: (.+)$')


def _parse_version(current):
    if not isinstance(current, str):
        raise ValueError(current)
    m = re.fullmatch(r'(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)', current)
    if not m:
        raise ValueError(current)
    return int(m.group(1)), int(m.group(2)), int(m.group(3))


def _analyze_commit(message):
    """Return (is_breaking, is_feature, is_fix) for a single commit message."""
    lines = message.split('\n')
    header = lines[0] if lines else ''
    m = _HEADER_RE.match(header)
    if not m:
        return False, False, False

    ctype = m.group(1)
    scope = m.group(3)
    breaking_bang = m.group(4) is not None
    text = m.group(5)

    # scope, if present, must be non-empty (regex already disallows empty
    # because group 3 requires at least one char of non-paren content).
    is_breaking = breaking_bang

    # Footer/body breaking markers apply only for commits whose header counts.
    for line in lines[1:]:
        if line.startswith('BREAKING CHANGE: ') or line.startswith('BREAKING-CHANGE: '):
            is_breaking = True
            break

    is_feature = ctype == 'feat'
    is_fix = ctype == 'fix'
    return is_breaking, is_feature, is_fix


def next_version(current, commits):
    """The version after `current`, decided by the commit messages. See TASK.md."""
    major, minor, patch = _parse_version(current)

    breaking = False
    feature = False
    fix = False
    for message in commits:
        b, f, fx = _analyze_commit(message)
        if b:
            breaking = True
        if f:
            feature = True
        if fx:
            fix = True

    if major == 0:
        if breaking:
            return '0.{}.0'.format(minor + 1)
        if feature or fix:
            return '0.{}.{}'.format(minor, patch + 1)
        return current
    else:
        if breaking:
            return '{}.0.0'.format(major + 1)
        if feature:
            return '{}.{}.0'.format(major, minor + 1)
        if fix:
            return '{}.{}.{}'.format(major, minor, patch + 1)
        return current
